# Terraform Dev/Prod Refactoring with `for_each`

## Strategy Overview

To achieve zero-diff state migrations when consolidating duplicated dev/prod blocks into a `for_each` module, you must:

1. **Use `terraform state mv`** to map old resource addresses to new module paths *before* applying the refactored code
2. **Keep resource names stable** within the module (don't rename)
3. **Validate with `terraform plan`** (must show no resource churn)

---

## Before: Duplicated Blocks Pattern

```hcl
# main.tf (original, duplicated)

# Dev environment
resource "aws_eks_cluster" "dev" {
  name            = "web-app-dev"
  version         = "1.28"
  role_arn        = aws_iam_role.eks_dev.arn

  vpc_config {
    subnet_ids = var.dev_subnet_ids
  }
}

resource "aws_eks_node_group" "dev" {
  cluster_name    = aws_eks_cluster.dev.name
  node_group_name = "dev-nodes"
  node_role_arn   = aws_iam_role.node_dev.arn
  subnet_ids      = var.dev_subnet_ids

  scaling_config {
    desired_size = 2
    max_size     = 3
    min_size     = 2
  }

  instance_types = ["t3.medium"]
}

resource "aws_s3_bucket" "dev" {
  bucket = "web-assets-dev-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_versioning" "dev" {
  bucket = aws_s3_bucket.dev.id
  versioning_configuration { status = "Enabled" }
}

# ... more dev resources ...

# Prod environment (copy-pasted with values changed)
resource "aws_eks_cluster" "prod" {
  name            = "web-app-prod"
  version         = "1.28"
  role_arn        = aws_iam_role.eks_prod.arn

  vpc_config {
    subnet_ids = var.prod_subnet_ids
  }
}

resource "aws_eks_node_group" "prod" {
  cluster_name    = aws_eks_cluster.prod.name
  node_group_name = "prod-nodes"
  node_role_arn   = aws_iam_role.node_prod.arn
  subnet_ids      = var.prod_subnet_ids

  scaling_config {
    desired_size = 4
    max_size     = 6
    min_size     = 4
  }

  instance_types = ["t3.large"]
